<?php require '../config.php';require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$s=$pdo->prepare("SELECT picture FROM products WHERE id=?");$s->execute([$id]);$row=$s->fetch();if($row){$s=$pdo->prepare("DELETE FROM products WHERE id=?");$s->execute([$id]);if($row['picture']&&strpos($row['picture'],'uploads/')===0){$path=__DIR__.'/../'. $row['picture'];if(is_file($path))unlink($path);}}header('Location: products.php');exit;?>